"""Round-trip tests for variance.xlsx (generated by build_wb.py)."""

import re

import pytest
from openpyxl import load_workbook

from build_wb import CENTERS, MONTHS, QUARTERS, SEED, generate_data

PATH = "variance.xlsx"

YTD_FORMULA_RE = re.compile(
    r"^='Q1'![A-Z]+\d+\+'Q2'![A-Z]+\d+\+'Q3'![A-Z]+\d+\+'Q4'![A-Z]+\d+$"
)

EXPECTED_SHEETS = ["Q1", "Q2", "Q3", "Q4", "YTD", "raw"]


@pytest.fixture(scope="module")
def wb():
    return load_workbook(PATH)


@pytest.fixture(scope="module")
def data():
    return generate_data()


# ---------------------------------------------------------------- structure

def test_sheet_names_and_order(wb):
    assert wb.sheetnames == EXPECTED_SHEETS


def test_raw_sheet_hidden(wb):
    assert wb["raw"].sheet_state == "hidden"


def test_visible_sheets_are_visible(wb):
    for name in ["Q1", "Q2", "Q3", "Q4", "YTD"]:
        assert wb[name].sheet_state == "visible"


# ------------------------------------------------------------- YTD formulas

def test_ytd_formulas_match_pattern(wb):
    ws = wb["YTD"]
    spot_cells = ["B2", "B5", "C3", "C7"]  # >= 3 spot cells
    matches = 0
    for addr in spot_cells:
        val = ws[addr].value
        assert isinstance(val, str) and val.startswith("="), f"{addr}: {val!r}"
        if YTD_FORMULA_RE.match(val):
            matches += 1
        # every formula references exactly the four quarter sheets in order
        refs = re.findall(r"'(Q\d)'!", val)
        assert refs == ["Q1", "Q2", "Q3", "Q4"], f"{addr}: {val!r}"
    assert matches >= 3


def test_ytd_variance_formula(wb):
    ws = wb["YTD"]
    assert ws["D2"].value == "=C2-B2"


# --------------------------------------------------- conditional formatting

@pytest.mark.parametrize("qname", ["Q1", "Q2", "Q3", "Q4"])
def test_conditional_formatting_cell_is_on_variance_range(wb, qname):
    ws = wb[qname]
    found = []
    for cf in ws.conditional_formatting:
        if str(cf.sqref) == "H2:J7":
            for rule in cf.rules:
                found.append(rule)
    assert found, f"no CF rule on H2:J7 of {qname}"
    rule = found[0]
    assert rule.type == "cellIs"
    assert rule.operator == "greaterThan"
    assert rule.formula == ["0.1*B2"]  # relative anchor: variance > 10% budget
    assert rule.dxf.fill.bgColor.rgb in ("00FF0000", "FFFF0000")


# ------------------------------------------- stored values vs recomputation

def _quarter_totals_from_raw(data):
    """Recompute per-center quarter + YTD totals from the flat data."""
    totals = {c: {"Q1": [0.0, 0.0], "Q2": [0.0, 0.0],
                  "Q3": [0.0, 0.0], "Q4": [0.0, 0.0],
                  "YTD": [0.0, 0.0]} for c in CENTERS}
    for c in CENTERS:
        for q, months in QUARTERS.items():
            for m in months:
                b, a = data[(c, m)]
                totals[c][q][0] += b
                totals[c][q][1] += a
            totals[c]["YTD"][0] += totals[c][q][0]
            totals[c]["YTD"][1] += totals[c][q][1]
    return totals


def test_quarter_sheets_match_generated_data(wb, data):
    for qname, months in QUARTERS.items():
        ws = wb[qname]
        for r, center in enumerate(CENTERS, start=2):
            assert ws.cell(row=r, column=1).value == center
            for i, month in enumerate(months):
                b, a = data[(center, month)]
                col = 2 + i * 3
                assert ws.cell(row=r, column=col).value == pytest.approx(b)
                assert ws.cell(row=r, column=col + 1).value == pytest.approx(a)
                assert ws.cell(row=r, column=col + 2).value \
                    == pytest.approx(round(a - b, 2))


def test_recomputed_ytd_equals_sum_of_quarter_values(wb, data):
    """Full Python recomputation: YTD (stored values) == sum of Q sheets."""
    totals = _quarter_totals_from_raw(data)
    ytd = wb["YTD"]

    # YTD value columns E/F/G must equal the recomputed totals...
    for r, center in enumerate(CENTERS, start=2):
        b, a = totals[center]["YTD"]
        v = round(a - b, 2)
        assert ytd.cell(row=r, column=1).value == center
        assert ytd.cell(row=r, column=5).value == pytest.approx(round(b, 2))
        assert ytd.cell(row=r, column=6).value == pytest.approx(round(a, 2))
        assert ytd.cell(row=r, column=7).value == pytest.approx(v)

    # ...and equal the sum of the four quarter-sheet total cells (K/L/M).
    for r, center in enumerate(CENTERS, start=2):
        sum_b = sum_a = 0.0
        for qname in ("Q1", "Q2", "Q3", "Q4"):
            qs = wb[qname]
            sum_b += qs.cell(row=r, column=11).value   # K: Total Budget
            sum_a += qs.cell(row=r, column=12).value   # L: Total Actual
        assert ytd.cell(row=r, column=5).value == pytest.approx(sum_b, abs=0.01)
        assert ytd.cell(row=r, column=6).value == pytest.approx(sum_a, abs=0.01)


# ------------------------------------------------------------ raw flat data

def test_raw_sheet_holds_flat_data(wb, data):
    ws = wb["raw"]
    assert [c.value for c in ws[1]] == \
        ["cost_center", "month", "budget", "actual", "variance"]
    rows = list(ws.iter_rows(min_row=2, values_only=True))
    assert len(rows) == len(CENTERS) * len(MONTHS) == 72
    by_key = {(r[0], r[1]): r for r in rows}
    for center in CENTERS:
        for month in MONTHS:
            b, a = data[(center, month)]
            row = by_key[(center, month)]
            assert row[2] == pytest.approx(b)
            assert row[3] == pytest.approx(a)
            assert row[4] == pytest.approx(round(a - b, 2))


def test_seed_reproducibility(data):
    assert generate_data() == data  # same seed -> identical dataset

